  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}
.confetti {
  position: absolute;
  width: 10px;
  height: 10px;
  top: -10px;
  animation: fallAndSpin linear infinite;
}
@keyframes fallAndSpin {
to {
    transform: translateY(100vh) rotate(360deg);
}
}
