.tooltip-container {
  position: relative;
  display: inline-block;
}
.tooltip-icon {
  cursor: pointer;
}
.tooltip-content {
  visibility: hidden;
  width: 320px;
  background-color: #004850;
  color: #fff;
  text-align: left;
  border-radius: 6px;
  padding: 10px;
  position: absolute;
  z-index: 1;
  top: 125%;
  left: 50%;
  margin-left: -150px;
  opacity: 0;
  transition: opacity 0.3s;
  white-space: pre-line;
  font-size: 14px;
}
.tooltip-icon:hover + .tooltip-content {
  visibility: visible;
  opacity: 1;
}
